#include <string.h>

int main() {
    char P[1005], A[1005];

    if (scanf("%s", P) != 1) return 0;
    if (scanf("%s", A) != 1) return 0;

    int countP[256] = {0};
    int countA[256] = {0};

    for (int i = 0; P[i] != '\0'; i++) {
        countP[(unsigned char)P[i]]++;
    }

    for (int i = 0; A[i] != '\0'; i++) {
        if (A[i] != '*') {
            countA[(unsigned char)A[i]]++;
        }
    }

    for (int i = 0; i < 256; i++) {
        if (countA[i] > countP[i]) {
            printf("N\n");
            return 0;
        }
    }

    printf("S\n");
    return 0;
}
